begin;

delete from public.version_banners vb
using public.game_versions gv, public.games g
where vb.version_id=gv.id and gv.game_id=g.id and g.code='YYS'
  and gv.version_no between 'YYS-2022-01-01' and 'YYS-2023-12-31';

with yys as (select id from public.games where code='YYS' limit 1),payload as (select $json$[{"version_no":"YYS-2022-01-26","version_name":"铃心踏焰","start_date":"2022-01-26","note":"","banners":[{"character":"铃彦姬","banner_type":"pickup"},{"character":"梦寻山兔","banner_type":"pickup"}]},{"version_no":"YYS-2022-02-16","version_name":"历史更新｜迦楼罗登场","start_date":"2022-02-16","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"迦楼罗","banner_type":"standard_addition"}]},{"version_no":"YYS-2022-03-09","version_name":"观山不见","start_date":"2022-03-09","note":"","banners":[{"character":"不见岳","banner_type":"pickup"}]},{"version_no":"YYS-2022-03-16","version_name":"历史更新｜影鳄登场","start_date":"2022-03-16","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"影鳄","banner_type":"standard_addition"}]},{"version_no":"YYS-2022-04-13","version_name":"残河溟夜·绮世物语第二弹","start_date":"2022-04-13","note":"绮世物语第二阶段内容更新。","banners":[{"character":"灵海蝶","banner_type":"standard_addition"}]},{"version_no":"YYS-2022-05-18","version_name":"高天原篇·邪神重归","start_date":"2022-05-18","note":"高天原篇大型剧情版本，版本活动核心为终焉审判。","banners":[{"character":"神堕八岐大蛇","banner_type":"pickup"}]},{"version_no":"YYS-2022-06-08","version_name":"历史更新｜粉婆婆登场","start_date":"2022-06-08","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"粉婆婆","banner_type":"standard_addition"}]},{"version_no":"YYS-2022-06-22","version_name":"不朽之目","start_date":"2022-06-22","note":"","banners":[{"character":"大夜摩天阎魔","banner_type":"pickup"}]},{"version_no":"YYS-2022-07-27","version_name":"枫火叶宴","start_date":"2022-07-27","note":"","banners":[{"character":"心狩鬼女红叶","banner_type":"pickup"}]},{"version_no":"YYS-2022-08-24","version_name":"鬼灭之刃联动·新角色","start_date":"2022-08-24","note":"","banners":[{"character":"我妻善逸","banner_type":"collab"},{"character":"嘴平伊之助","banner_type":"collab"},{"character":"灶门炭治郎","banner_type":"rerun"},{"character":"灶门祢豆子","banner_type":"rerun"}]},{"version_no":"YYS-2022-09-21","version_name":"六周年·千年之守","start_date":"2022-09-21","note":"国服六周年大型版本。","banners":[{"character":"须佐之男","banner_type":"pickup"},{"character":"神启荒","banner_type":"pickup"}]},{"version_no":"YYS-2022-10-19","version_name":"寻世香行","start_date":"2022-10-19","note":"","banners":[{"character":"寻香行","banner_type":"pickup"}]},{"version_no":"YYS-2022-11-23","version_name":"化四季","start_date":"2022-11-23","note":"","banners":[{"character":"季","banner_type":"pickup"}]},{"version_no":"YYS-2022-12-21","version_name":"镜守云归","start_date":"2022-12-21","note":"","banners":[{"character":"禅心云外镜","banner_type":"pickup"}]},{"version_no":"YYS-2023-01-18","version_name":"月影焕流光","start_date":"2023-01-18","note":"","banners":[{"character":"月读","banner_type":"pickup"},{"character":"流光追月神","banner_type":"pickup"}]},{"version_no":"YYS-2023-02-22","version_name":"修罗猎戏","start_date":"2023-02-22","note":"","banners":[{"character":"修罗鬼童丸","banner_type":"pickup"}]},{"version_no":"YYS-2023-03-11","version_name":"历史更新｜天逆每登场","start_date":"2023-03-11","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"天逆每","banner_type":"standard_addition"}]},{"version_no":"YYS-2023-03-29","version_name":"万言归灵","start_date":"2023-03-29","note":"","banners":[{"character":"言灵","banner_type":"pickup"}]},{"version_no":"YYS-2023-04-26","version_name":"银之绮都·银魂联动","start_date":"2023-04-26","note":"《银魂》联动。","banners":[{"character":"坂田银时","banner_type":"collab"},{"character":"神乐&定春","banner_type":"collab"}]},{"version_no":"YYS-2023-05-24","version_name":"祈舞唤神","start_date":"2023-05-24","note":"","banners":[{"character":"孔雀明王","banner_type":"pickup"}]},{"version_no":"YYS-2023-06-07","version_name":"契灵之境","start_date":"2023-06-07","note":"永久系统型大型更新：契灵相关玩法/系统开放。","banners":[]},{"version_no":"YYS-2023-06-28","version_name":"归鹿之途","start_date":"2023-06-28","note":"","banners":[{"character":"寻森小鹿男","banner_type":"pickup"}]},{"version_no":"YYS-2023-07-12","version_name":"历史更新｜慧明灯登场","start_date":"2023-07-12","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"慧明灯","banner_type":"standard_addition"}]},{"version_no":"YYS-2023-07-26","version_name":"再结前缘","start_date":"2023-07-26","note":"","banners":[{"character":"纺愿缘结神","banner_type":"pickup"}]},{"version_no":"YYS-2023-08-23","version_name":"雾山问道","start_date":"2023-08-23","note":"《雾山五行》联动。","banners":[{"character":"闻人翊悬","banner_type":"collab"}]},{"version_no":"YYS-2023-09-20","version_name":"七周年·佑世之光","start_date":"2023-09-20","note":"国服七周年大型版本。","banners":[{"character":"天照","banner_type":"pickup"},{"character":"渺念萤草","banner_type":"pickup"}]},{"version_no":"YYS-2023-10-18","version_name":"神代终局","start_date":"2023-10-18","note":"","banners":[{"character":"伊邪那美","banner_type":"pickup"}]},{"version_no":"YYS-2023-10-25","version_name":"历史更新｜盗人神登场","start_date":"2023-10-25","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"盗人神","banner_type":"standard_addition"}]},{"version_no":"YYS-2023-11-15","version_name":"红狐之邀","start_date":"2023-11-15","note":"客户端版本：1.7.74。","banners":[{"character":"本真三尾狐","banner_type":"pickup"}]}]$json$::jsonb data),
vr as(select x from payload cross join lateral jsonb_array_elements(data)x),
upserted as (
 insert into public.game_versions(game_id,version_no,version_name,start_date,note)
 select yys.id,x->>'version_no',x->>'version_name',(x->>'start_date')::date,nullif(x->>'note','') from yys cross join vr
 on conflict(game_id,version_no) do update set version_name=excluded.version_name,start_date=excluded.start_date,note=excluded.note,updated_at=now()
 returning id,version_no
),
br as(select x->>'version_no' version_no,b from vr cross join lateral jsonb_array_elements(coalesce(x->'banners','[]'::jsonb))b)
insert into public.version_banners(version_id,phase,banner_type,character_id,character_name_raw)
select u.id,case when br.b->>'banner_type'='standard_addition' then 'standard' else 'other' end,br.b->>'banner_type',c.id,br.b->>'character'
from br join upserted u using(version_no)
left join public.characters c on c.game_id=(select id from yys) and c.name=br.b->>'character';

commit;
